{ 
  "description": "The creature is a large quadrupedal mammal shown in right-facing profile standing on a plain light background. Its entire body except for the dorsal surface is covered in dense, shaggy brown fur that is lighter tan on the muzzle and darker on the lower legs. The head is broad and bear-like with a blunt muzzle and black nose. Covering the back from the back of the head to just above the rump is a large, glossy, dark brown to black segmented carapace that sits on top of the fur, with a long, smooth, strongly recurved horn projecting forward and upward from the forehead area. The animal stands on four thick, furred limbs ending in clawed paws and has a short furry tail at the rear.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad bear-like head with brown fur, lighter tan fur on the muzzle and around the mouth, a large black nose at the tip, small dark brown eyes, and a closed mouth",
      "where": "at the front right end of the body, facing right"
    },
    {
      "part": "horns",
      "looks_like": "single long glossy black horn, smooth, tapering to a sharp point, strongly arched backward then forward over the head, with a small pointed notch on the inner curve near the base",
      "where": "arising from the dark plate on the forehead between the two ears and curving up and forward"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in brown fur, with slightly lighter inner edges",
      "where": "on top of the head on either side of the horn base"
    },
    {
      "part": "legs",
      "looks_like": "four thick, heavily furred brown legs with shaggy hair, two forelegs under the chest and two hindlegs under the hips",
      "where": "supporting the body from below, extending from the torso to the ground"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws with brown fur and visible dark curved claws on the toes",
      "where": "at the bottom ends of each leg in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "short, stubby, bushy tail covered in brown fur",
      "where": "at the far left rear end of the body above the hind legs"
    },
    {
      "part": "shell",
      "looks_like": "large glossy dark brown-black exoskeleton covering the dorsal side, smooth and shiny with light reflections, extending from the neck to the rump",
      "where": "on top of the back, sitting over the fur from behind the head to above the tail, with side flaps hanging down over the shoulders and mid-body"
    },
    {
      "part": "plates",
      "looks_like": "overlapping segmented plates forming the shell: a large smooth shoulder shield, three smaller pointed neck plates behind the head, five to six transverse back plates with visible sutures, and lateral rows of oval light-brown openings bordered by dark rings with small circular holes below",
      "where": "composing the entire dorsal shell and its side extensions along the back and neck"
    }
  ],
  "attached_objects": [],
  "animals": ["bear", "rhinoceros beetle"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
